-- SharonPly website database
--
-- Import once into an EMPTY database (phpMyAdmin → Import, or:
--   mysql -u USER -p DATABASE_NAME < sharonply-database.sql).
-- Creates the three tables the website uses and loads 93 dealers and
-- 24 sales team members. Form submissions start empty and fill as visitors send forms.

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS dealers (
  id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  contact_person VARCHAR(255),
  address TEXT,
  city VARCHAR(100) NOT NULL,
  state VARCHAR(100) NOT NULL,
  pincode VARCHAR(20),
  phone VARCHAR(255),
  email VARCHAR(255),
  website VARCHAR(500),
  division VARCHAR(50) NOT NULL DEFAULT 'Both',
  lat DOUBLE,
  lng DOUBLE,
  active TINYINT(1) NOT NULL DEFAULT 1,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sales_team (
  id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  designation VARCHAR(255),
  department VARCHAR(100),
  phone VARCHAR(50),
  email VARCHAR(255),
  region VARCHAR(255),
  division VARCHAR(50) NOT NULL DEFAULT 'Plywood',
  cities TEXT,
  photo_url VARCHAR(500),
  linkedin VARCHAR(500),
  sort_order INT DEFAULT 0,
  active TINYINT(1) NOT NULL DEFAULT 1,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS form_submissions (
  id INT AUTO_INCREMENT PRIMARY KEY,
  type VARCHAR(50) NOT NULL,
  source VARCHAR(100),
  name VARCHAR(255),
  email VARCHAR(255),
  phone VARCHAR(50),
  city VARCHAR(100),
  subject VARCHAR(255),
  message TEXT,
  product VARCHAR(255),
  role VARCHAR(255),
  experience VARCHAR(100),
  metadata JSON,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


